INSERT IGNORE INTO user_module_access (user_id, module_id, created_at) SELECT DISTINCT a.user_id, m.module_id, NOW() FROM user_module_access a JOIN modules ma ON ma.module_id = a.module_id AND ma.system_id = 'e-trade' JOIN modules m ON m.system_id = 'e-trade';
