-- Vídeos oficiais do E-Trade Web (canal VR Tech, playlist E-Trade Web) organizados por módulo.
-- Substitui as aulas de exemplo (sem vídeo) do E-Trade. Não mexe em aulas que já têm vídeo.
DELETE l FROM lessons l JOIN modules m ON m.module_id = l.module_id WHERE m.system_id = 'e-trade' AND l.origin = 'demo' AND l.video_source = 'none';
UPDATE modules SET position = 1 WHERE system_id = 'e-trade' AND name = 'Primeiros passos';
UPDATE modules SET position = 2 WHERE system_id = 'e-trade' AND name = 'Cadastros';
UPDATE modules SET position = 3 WHERE system_id = 'e-trade' AND name = 'Produtos e estoque';
UPDATE modules SET position = 4 WHERE system_id = 'e-trade' AND name = 'Vendas e faturamento';
UPDATE modules SET position = 5 WHERE system_id = 'e-trade' AND name = 'Emissão de NF-e e NFC-e';
UPDATE modules SET position = 6 WHERE system_id = 'e-trade' AND name = 'Frente de caixa (PDV)';
UPDATE modules SET position = 7 WHERE system_id = 'e-trade' AND name = 'Financeiro';
UPDATE modules SET position = 8 WHERE system_id = 'e-trade' AND name = 'Relatórios';
UPDATE modules SET position = 9 WHERE system_id = 'e-trade' AND name = 'Ordem de serviço';
UPDATE modules SET position = 10 WHERE system_id = 'e-trade' AND name = 'Integrações';
DELETE m FROM modules m WHERE m.system_id = 'e-trade' AND m.name NOT IN ('Primeiros passos','Cadastros','Produtos e estoque','Vendas e faturamento','Emissão de NF-e e NFC-e','Frente de caixa (PDV)','Financeiro','Relatórios','Ordem de serviço','Integrações') AND NOT EXISTS (SELECT 1 FROM lessons l WHERE l.module_id = m.module_id);
UPDATE modules SET position = position + 100 WHERE system_id = 'e-trade' AND name NOT IN ('Primeiros passos','Cadastros','Produtos e estoque','Vendas e faturamento','Emissão de NF-e e NFC-e','Frente de caixa (PDV)','Financeiro','Relatórios','Ordem de serviço','Integrações');
UPDATE systems SET description = 'Gestão de vendas, estoque, financeiro e frente de loja na web, com emissão de NF-e e NFC-e.' WHERE system_id = 'e-trade';
